import {BUILD,MATERIALS,SITES,FACTS,PEOPLE,esc,localURL,addressTarget} from './registry.js';
let QUESTIONS=[],STANCES={},verifyClaim=()=>({ok:false}),phaseReady=()=>false,checkMarks=()=>({ok:false});
let proofLoaded;
async function loadProof(){return proofLoaded??=import('./proof-engine.js').then(m=>{({QUESTIONS,STANCES,verifyClaim,phaseReady,checkMarks}=m);});}

const HINTS={meal:['夜宵回执和那天桌上的照片，都比“我记得”具体。','购买、吃过和感染来源，是三个不同判断。比较收据与照片/记事本能回答哪一个。','收集夜宵回执，以及桌面照片或宿舍记录。在推理台引用它们，把“共餐足以确认来源”标为证据不足。'],deleted:['找文件编号，不必看私人信的全文。','“三张”是数量，F1018和R0315才标明它们分别属于哪一组。','用照片袋目录、校刊接收清单，加上删除请求或宿舍记录。F1018来自去年10月，报告是今年3月。'],source:['同模板与同一张用过的纸，区别在哪？','格线和印章可能重复；观察折痕、后来写下的笔迹，再找收稿原件。','在原件对照中勾选纸面折痕、后加笔迹；引用by原件、第三张图和收稿清单。“独立计作第三位就诊者”应有反证。校刊凭证为HS032316。'],return:['视频里看见了什么，登记表又多说了什么？','背影不能认脸；还要核对同一时段的设备交接。下午返校与上午就医并不冲突。','摄影社登记实拍03-21、机位B，提取码0321B。引用请假原话、相册、交接场记，只反驳“全天不在校”。'],access:['公用阅览的格式和本期信息分开写着。','HS是校刊缩写，收稿日取月日，本期16与下期17要区分。相册则用实拍日加机位。','校刊共享凭证HS032316，相册0321B；不需要破解任何人私人账号。']};

export function mountNotebook(store,{site=document.body.dataset.site}={}){
 const shell=document.createElement('aside');shell.className='qn-shell';shell.innerHTML=`<button type="button" class="qn-toggle" aria-expanded="false" aria-controls="qn-drawer">✎ 随身调查本 <span class="qn-dot" hidden aria-label="有新记录"></span></button><section class="qn-drawer" id="qn-drawer" aria-label="随身调查本" hidden><div class="qn-heading"><strong>随身调查本</strong><div><button data-pin type="button" aria-pressed="false" title="固定在一旁，边读边记">固定</button><button data-close type="button" aria-label="收起调查本">×</button></div></div><nav class="qn-tabs" aria-label="调查本分区">${[['archive','资料夹'],['reason','推理台'],['timeline','时间线'],['bookmarks','书签'],['notes','手记'],['help','提示/备份']].map(([id,t])=>`<button data-tab="${id}" aria-selected="false" type="button">${t}</button>`).join('')}</nav><div class="qn-body"></div><footer class="qn-footer">《第三份阳性报告》· v${BUILD} 候选样章<br>虚构校园与人物；材料不构成医疗判断。旧版存档单独留存。</footer></section><div class="qn-toast" role="status" hidden></div>`;document.body.append(shell);
 const toggle=shell.querySelector('.qn-toggle'),drawer=shell.querySelector('.qn-drawer'),body=shell.querySelector('.qn-body'),dot=shell.querySelector('.qn-dot'),toast=shell.querySelector('.qn-toast');let tab='archive',pinned=false,toastTimer,filter='',draft={question:'meal',stance:'pending',note:'',sources:[]},editing=null,loadedImage=false;
 function feedback(message,{pulse=false}={}){toast.textContent=message;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3600);if(pulse){dot.hidden=false;toggle.classList.remove('qn-pulse');requestAnimationFrame(()=>toggle.classList.add('qn-pulse'));}}
 function fitDrawer(){const zoom=Number(getComputedStyle(document.documentElement).zoom)||1;for(const prop of ['position','top','right','bottom','width','height'])drawer.style.removeProperty(prop);if(zoom>1.01){Object.assign(drawer.style,{position:'fixed',top:12/zoom+'px',right:12/zoom+'px',bottom:'auto',width:(innerWidth-24)/zoom+'px',height:(innerHeight-24)/zoom+'px'});}}
 window.addEventListener('resize',fitDrawer);
 function open(){fitDrawer();drawer.hidden=false;toggle.setAttribute('aria-expanded','true');dot.hidden=true;toggle.classList.remove('qn-pulse');render();shell.querySelector('[data-close]').focus();}
 function close(){drawer.hidden=true;toggle.setAttribute('aria-expanded','false');pinned=false;document.body.classList.remove('qn-pinned');shell.querySelector('[data-pin]').setAttribute('aria-pressed','false');toggle.focus();}
 const count=()=>Object.keys(store.get().evidence).length;
 function archive(){const s=store.get(),ids=Object.keys(s.evidence).filter(id=>{const m=MATERIALS[id];return `${m.title} ${m.person?(PEOPLE[m.person]?.name||m.person):''} ${m.event} ${SITES[m.site].name}`.toLowerCase().includes(filter.toLowerCase());});return `<h3>已归档 ${count()} 份</h3><p class="qn-tip">收录只表示材料可回查，不等于它的说法已经证实。同源转载会标注原件关系。</p><input class="qn-filter" name="archiveFilter" data-filter placeholder="人物、日期或站点" aria-label="筛选归档" value="${esc(filter)}"><div data-archive-list>${ids.map(id=>{const m=MATERIALS[id];return `<article class="qn-card"><a href="${localURL(m.path)}">${esc(m.title)}</a><small>${esc(SITES[m.site].name)} · ${esc(m.event)} · ${esc(m.type)}${m.copy_of?' · 副本，原件：'+esc(MATERIALS[m.copy_of].title):''}</small><details><summary>归档内容 / 来源</summary><div class="qn-snapshot">${esc(s.snapshots?.[id]?.value?.text||m.title+'\n原件地址保留，可点击标题重读。')}</div><small>形成来源：${esc(m.origin)}</small></details></article>`;}).join('')||'<p class="qn-muted">还没有匹配的资料。浏览原件时会自动收入这里。</p>'}</div>`;}
 function reason(){const s=store.get(),hyp=Object.entries(s.hypotheses).filter(([,h])=>h.value),proofs=hyp.map(([id,h])=>{const p=verifyClaim(s,h.value);return `<article class="qn-card ${p.ok?'qn-confirmed':''}"><strong>${esc(QUESTIONS.find(q=>q.id===h.value.question)?.text||h.value.question)}</strong><small>${esc(STANCES[h.value.stance]||'暂不判断')} · ${p.ok?'来源关系已核对':'尚待核对'}</small><p>${esc(h.value.note)}</p><small>引用：${h.value.sources.map(id=>esc(MATERIALS[id]?.title)).join('、')}</small><button data-edit="${id}">修改</button> <button data-remove="${id}">撤回判断</button></article>`;});return `<h3>观察 → 假设 → 反证</h3><p class="qn-tip">下面的话只是待核对说法。你选择立场并引用原件，系统只检查证明范围，不按你读材料的顺序判定。</p><form data-proof class="qn-stack"><label>要核对的说法<select name="question" style="width:100%">${QUESTIONS.map(q=>`<option value="${q.id}" ${draft.question===q.id?'selected':''}>${esc(q.text)}</option>`).join('')}</select></label><label>目前判断 <select name="stance">${Object.entries(STANCES).map(([id,t])=>`<option value="${id}" ${draft.stance===id?'selected':''}>${t}</option>`).join('')}</select></label><label>我的理由<textarea name="note" maxlength="3000" placeholder="材料里哪一个细节改变了你的想法？">${esc(draft.note)}</textarea></label><fieldset><legend>引用已收原件（可多选）</legend><div class="qn-options">${Object.keys(s.evidence).map(id=>`<label><input type="checkbox" name="sources" value="${id}" ${draft.sources.includes(id)?'checked':''}>${esc(MATERIALS[id].title)}</label>`).join('')||'<span>先浏览几份原件。</span>'}</div></fieldset><div class="qn-row"><button type="submit">记下并核对</button><button type="button" data-blank>另起一个判断</button></div><div class="qn-result qn-proof-result" data-proof-result role="status"></div></form><details data-compare><summary>原件对照 / 我的观察标记</summary><p class="qn-muted">可调整叠层与位移，对齐两张图。使用键盘方向键也能调节滑条。</p>${s.evidence.reportBy&&s.evidence.anonymous?`<div class="qn-compare-stage"><img src="${localURL('assets/report-by.svg')}" alt="by的原报告"><img class="qn-overlay" src="${localURL('assets/report-anonymous.svg')}" alt="第三张图的半透明叠层"></div><label>叠层透明度<input type="range" data-opacity min="0" max="100" value="50"></label><div class="qn-row"><label>横移<input type="range" data-offset="x" min="-25" max="25" value="0"></label><label>纵移<input type="range" data-offset="y" min="-25" max="25" value="0"></label></div><form data-marks><p class="qn-muted">哪些特征能用于辨认同一原件？至少两项。</p><div class="qn-options">${[['fold','纸面折痕'],['pen','后加笔迹'],['number','完整报告编号'],['template','表格横线'],['seal','印章角度'],['noise','打印底噪']].map(([id,t])=>`<label><input type="checkbox" name="marks" value="${id}" ${s.marks.report?.value.includes(id)?'checked':''}>${t}</label>`).join('')}</div><button>记录观察</button><p class="qn-result" data-marks-result role="status"></p></form>`:'<p>先打开两份报告图，再把它们放在一起。</p>'}</details><h4>我的判断记录</h4>${proofs.join('')||'<p class="qn-muted">还没有记下假设。错误假设可以修改，不会损坏原件。</p>'}${phaseReady(s)?`<section class="qn-card qn-confirmed" data-phase-complete><h4>阶段说明已整理</h4><p>我把共餐、删照片、图像复制和返校分开了。现在能排除几种解释，也留下了需要向本人核实的问题。</p><p>第三张图不能独立计作第三名患者。谁编辑、谁提交，仍要相关源文件；感染来源也还不能下结论。</p><p class="qn-muted">P1候选样章到这里。全剧本将在六人盲测反馈通过后扩写。可在“提示/备份”导出本轮记录。</p></section>`:''}`;}
 function timeline(){return `<h3>时间并不只有一种</h3><p class="qn-tip">事件发生、文书录入、文件上传要分开看。基准是你的标注，可随时改。</p>${Object.keys(store.get().evidence).map(id=>{const m=MATERIALS[id];return `<article class="qn-card qn-timeline"><strong>${esc(m.title)}</strong><p>事件 <time>${m.event}</time><br>录入 / 上传 <time>${m.recorded}</time></p><label>基准 <select data-time="${id}">${[['unknown','未标注'],['server','服务器记录'],['display','设备屏显'],['capture','实拍/形成时间'],['memory','当事人回忆']].map(([v,t])=>`<option value="${v}" ${store.get().timeline[id]?.value===v?'selected':''}>${t}</option>`).join('')}</select></label></article>`;}).join('')}`;}
 function bookmarks(){return `<h3>已发现的站点</h3><form data-address><label for="qn-address">地址 / BV号 / 内网直达</label><div class="qn-row"><input id="qn-address" name="address" placeholder="粘贴你看到的地址或BV号" autocomplete="off" required style="flex:1;min-width:100px"><button>前往</button></div><p data-address-result class="qn-result" role="status"></p></form><nav class="qn-bookmarks">${store.get().discovered_sites.map(id=>`<a href="${localURL(SITES[id].path)}">${esc(SITES[id].name)} ↗</a>`).join('')}</nav>`;}
 function help(){return `<h3>提示与存档</h3><p class="qn-muted">主动展开才会显示提示。每一层都可能透露更多思路。</p>${Object.entries(HINTS).map(([id,steps])=>`<details class="qn-hint"><summary>${id==='access'?'共享阅览 / 相册':esc(QUESTIONS.find(q=>q.id===id)?.text)}</summary><p>一级：${steps[0]}</p><details><summary>二级：比较方法</summary><p>${steps[1]}</p><details><summary>三级：完整步骤（剧透）</summary><p>${steps[2]}</p></details></details></details>`).join('')}<hr><p class="qn-status" data-save-status>${esc(store.status().message||'活动进度保存在本机；旧版原始存档已单独归档。')}</p><div class="qn-row"><button data-export>导出完整调查本</button><label>恢复导出文件 <input data-import type="file" accept="application/json,.json"></label></div><button data-export-legacy style="margin-top:9px">导出本机旧版原始存档</button>${Object.entries(store.get().legacyImports||{}).map(([id])=>`<button data-export-imported="${id}" style="margin-top:8px">导出恢复文件携带的旧档</button>`).join('')}<p class="qn-result" data-backup-result role="status"></p><details><summary>候选版与测试说明</summary><p>P0设计已冻结，当前仅P1正式质量候选样章。未完成商业作品实机对照与6人盲测，不宣称达到3—5小时完整作品或正式发布标准。</p><p><a href="${localURL('playtest.html')}">打开无剧透测试说明</a></p></details>`;}
 function render(){if(drawer.hidden)return;const focused=body.contains(document.activeElement)?document.activeElement:null;const focusName=focused?.name,selection=focused&&'selectionStart'in focused?focused.selectionStart:null,scroll=body.scrollTop;for(const b of shell.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===tab));body.innerHTML=tab==='archive'?archive():tab==='reason'?reason():tab==='timeline'?timeline():tab==='bookmarks'?bookmarks():tab==='notes'?`<h3>自由手记</h3><p class="qn-muted">写自己的话；保存不会将它当作事实。</p><form data-notes><textarea name="personal" style="min-height:260px" maxlength="12000">${esc(store.get().notes.personal?.value||'')}</textarea><button>保存手记</button><p data-note-result class="qn-result" role="status"></p></form>`:help();body.scrollTop=scroll;if(focusName){const restored=body.querySelector(`[name="${focusName}"]`);restored?.focus({preventScroll:true});if(selection!==null&&restored?.setSelectionRange)try{restored.setSelectionRange(selection,selection);}catch{}}}
 const captureDraft=()=>{const f=body.querySelector('[data-proof]');if(f)draft={question:f.elements.question.value,stance:f.elements.stance.value,note:f.elements.note.value,sources:[...f.querySelectorAll('[name=sources]:checked')].map(i=>i.value)};};
 const setResult=(selector,message)=>{const el=body.querySelector(selector);if(el)el.textContent=message;};
 toggle.addEventListener('click',()=>drawer.hidden?open():close());shell.querySelector('[data-close]').addEventListener('click',close);
 shell.querySelector('[data-pin]').addEventListener('click',e=>{pinned=!pinned;document.body.classList.toggle('qn-pinned',pinned);e.currentTarget.setAttribute('aria-pressed',String(pinned));});
 const outside=e=>{if(!drawer.hidden&&!pinned&&!shell.contains(e.target))close();};document.addEventListener('pointerdown',outside);const key=e=>{if(e.key==='Escape'&&!drawer.hidden){e.preventDefault();close();}};document.addEventListener('keydown',key);
 shell.addEventListener('input',e=>{captureDraft();if(e.target.matches('[data-filter]')&&!e.isComposing){filter=e.target.value;render();body.querySelector('[data-filter]')?.focus();}if(e.target.matches('[data-opacity]'))body.querySelector('.qn-overlay').style.opacity=Number(e.target.value)/100;if(e.target.dataset.offset)body.querySelector('.qn-overlay').style.setProperty('--'+e.target.dataset.offset,e.target.value+'px');});
 shell.addEventListener('change',async e=>{captureDraft();if(e.target.dataset.time)await store.update('timeline',e.target.dataset.time,e.target.value);if(e.target.matches('[data-import]')){const file=e.target.files?.[0];if(!file)return;if(file.size>2500000)return setResult('[data-backup-result]','文件过大，未导入。');let result;try{result=await store.restore(await file.text());}catch{result={message:'文件无法读取，当前进度未变更。'};}setResult('[data-backup-result]',result.message);}});
 function download(data,name,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 shell.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.tab){captureDraft();if(['reason','help'].includes(t.dataset.tab))await loadProof();tab=t.dataset.tab;body.scrollTop=0;render();}if(t.hasAttribute('data-blank')){editing=null;draft={question:'meal',stance:'pending',note:'',sources:[]};render();}if(t.dataset.edit){editing=t.dataset.edit;draft=structuredClone(store.get().hypotheses[editing].value);render();}if(t.dataset.remove){await store.update('hypotheses',t.dataset.remove,null);feedback('已撤回判断，原始材料仍在。');}if(t.hasAttribute('data-export'))download(JSON.stringify(await store.export(),null,2),'青禾调查本-v4.json');if(t.dataset.exportImported){download(store.get().legacyImports[t.dataset.exportImported].value.raw,'青禾恢复文件内的旧档.json');}if(t.hasAttribute('data-export-legacy')){const data=await store.export();download(data.legacy.raw,'青禾旧版原始存档.json');}});
 shell.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.matches('[data-proof]')){captureDraft();const result=verifyClaim(store.get(),draft);const saved=await store.update('hypotheses',editing||crypto.randomUUID(),structuredClone(draft));if(saved.ok){if(result.ok)feedback('判断与引用关系已核对。',{pulse:true});setResult('[data-proof-result]',result.message);}else setResult('[data-proof-result]',saved.message);}if(f.matches('[data-marks]')){const marks=[...f.querySelectorAll(':checked')].map(i=>i.value),result=checkMarks(marks);if(result.ok)await store.update('marks','report',marks);setResult('[data-marks-result]',result.message);const detail=body.querySelector('[data-compare]');if(detail)detail.open=true;}if(f.matches('[data-address]')){const target=addressTarget(f.elements.address.value);if(target)location.assign(localURL(target));else setResult('[data-address-result]','没有找到这个地址。请核对完整BV号或帖子中的内网域名。');}if(f.matches('[data-notes]')){const result=await store.update('notes','personal',f.elements.personal.value);setResult('[data-note-result]',result.ok?'手记已保存。':result.message);}});
 const unsubscribe=store.subscribe((_s,meta)=>{captureDraft();if(meta.kind==='collect'&&!meta.result?.duplicate)feedback('已归档：'+MATERIALS[meta.result.id]?.title,{pulse:true});if(meta.kind==='discover'&&!meta.result?.duplicate)feedback('已将【'+SITES[meta.result.site]?.name+'】添加至调查书签',{pulse:true});if(meta.kind==='storage-error')feedback(meta.status.message);const typing=body.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select');if(!typing||['hypotheses','marks','restore'].includes(meta.kind))render();});
 if(!store.status().persistent)feedback(store.status().message,{pulse:true});
 return {feedback,open,close,dispose(){unsubscribe();window.removeEventListener('resize',fitDrawer);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key);clearTimeout(toastTimer);shell.remove();}};
}
